mapper.select:
SELECT id, schedule_id, seat_no, status, order_id, lock_time, lock_user_id
FROM schedule_seat WHERE schedule_id = #{scheduleId}
ORDER BY seat_no

mapper.update:
UPDATE schedule_seat
SET status = 'LOCKED', order_id = #{orderId}, lock_user_id = #{lockUserId}, lock_time = #{lockTime}
WHERE schedule_id = #{scheduleId} AND seat_no = #{seatNo}
  AND (status = 'AVAILABLE'
       OR (status = 'LOCKED' AND lock_user_id = #{lockUserId} AND #{lockUserId} IS NOT NULL))

UPDATE schedule_seat
SET status = 'AVAILABLE', order_id = NULL, lock_time = NULL, lock_user_id = NULL
WHERE schedule_id = #{scheduleId} AND seat_no = #{seatNo}

UPDATE schedule_seat
SET status = 'AVAILABLE', order_id = NULL, lock_time = NULL, lock_user_id = NULL
WHERE schedule_id = #{scheduleId} AND seat_no = #{seatNo} AND order_id = #{orderId}

UPDATE schedule_seat
SET status = 'AVAILABLE', order_id = NULL, lock_time = NULL, lock_user_id = NULL
WHERE schedule_id = #{scheduleId} AND seat_no = #{seatNo}
  AND status = 'LOCKED' AND order_id IS NULL AND lock_user_id = #{lockUserId}

UPDATE schedule_seat
SET status = 'AVAILABLE', order_id = NULL, lock_time = NULL, lock_user_id = NULL
WHERE order_id = #{orderId}

mapper.select:
SELECT id, schedule_id, seat_no, status, order_id, lock_time, lock_user_id
FROM schedule_seat
WHERE status = 'LOCKED' AND lock_time < #{now}

mapper.update:
